def mha(self, key, value, q, k, h, d, mask=None):
    if not isinstance(key, Tensor):
        raise TypeError("key must be a Tensor")
    if not isinstance(value, Tensor):
        raise TypeError("value must be a Tensor")
    # The four dimensions must be non-bool positive ints.
    for name, dim in (("q", q), ("k", k), ("h", h), ("d", d)):
        if isinstance(dim, bool) or not isinstance(dim, int):
            raise TypeError(name + " must be a positive int")
        if dim <= 0:
            raise ValueError(name + " must be a positive int")
    # All three operands must hold non-empty 1D finite float lists;
    # data may have been mutated after construction, so re-validate at
    # call time. self is the h*q*d queries, key the h*k*d keys and
    # value the h*k*d values, all flattened by token, head and feature
    # dimension: index ((token*h + head)*d + r).
    q_data = _require_nonempty_float_vector(self, "mha")
    k_data = _require_nonempty_float_vector(key, "mha")
    v_data = _require_nonempty_float_vector(value, "mha")
    if len(q_data) != q * h * d:
        raise ValueError("query length must equal q * h * d")
    if len(k_data) != k * h * d:
        raise ValueError("key length must equal k * h * d")
    if len(v_data) != k * h * d:
        raise ValueError("value length must equal k * h * d")
    # mask is either None (every position allowed) or a length q*k
    # flat list of bools shared by every head, one per query/key pair
    # in row-major order; every query row must allow at least one
    # position.
    if mask is None:
        mask_list = [True] * (q * k)
    else:
        if not isinstance(mask, list):
            raise TypeError("mask must be a list of bools")
        if len(mask) != q * k:
            raise ValueError("mask length must equal q * k")
        for flag in mask:
            if not isinstance(flag, bool):
                raise TypeError("mask elements must be bools")
        mask_list = list(mask)
        for i in range(q):
            base = i * k
            if not any(mask_list[base:base + k]):
                raise ValueError("each mask row must contain a true value")
    # Snapshot the inputs at call time so later caller-side mutation
    # or replacement of any data list or the mask can change neither
    # the forward result nor a pending backward pass.
    snapshot_q = list(q_data)
    snapshot_k = list(k_data)
    snapshot_v = list(v_data)
    snapshot_mask = mask_list

    def qi(head, i, r):
        return (i * h + head) * d + r

    def ki(head, j, r):
        return (j * h + head) * d + r

    scale = math.sqrt(float(d))
    if not math.isfinite(scale):
        raise ValueError("mha intermediate must be finite")
    # Scores: s[head,i,j] = (sum_r Q[head,i,r]*K[head,j,r]) / sqrt(d),
    # accumulated from 0.0 in ascending (i, j, head, r) order. A
    # non-finite product, partial sum or scaled score aborts before a
    # result tensor exists, so no state can change on failure.
    scores = [0.0] * (h * q * k)
    for i in range(q):
        for j in range(k):
            for head in range(h):
                acc = 0.0
                for r in range(d):
                    product = (
                        snapshot_q[qi(head, i, r)]
                        * snapshot_k[ki(head, j, r)]
                    )
                    if not math.isfinite(product):
                        raise ValueError("mha intermediate must be finite")
                    acc += product
                    if not math.isfinite(acc):
                        raise ValueError("mha intermediate must be finite")
                score = acc / scale
                if not math.isfinite(score):
                    raise ValueError("mha intermediate must be finite")
                scores[(head * q + i) * k + j] = score
    # Per-head per-row stable softmax over the allowed positions only,
    # in ascending (i, head, j) key order: m = row max of the allowed
    # scores, z_j = exp(s_j - m), s = sum(z), p_j = z_j / s; masked
    # positions stay 0.0. exp is only ever evaluated on values in
    # (-inf, 0]; exp(s_j) directly is never computed.
    probs = [0.0] * (h * q * k)
    for i in range(q):
        base = i * k
        allowed = [j for j in range(k) if snapshot_mask[base + j]]
        for head in range(h):
            sbase = (head * q + i) * k
            m = max(scores[sbase + j] for j in allowed)
            z = [0.0] * k
            row_sum = 0.0
            for j in allowed:
                diff = scores[sbase + j] - m
                if not math.isfinite(diff):
                    raise ValueError("mha intermediate must be finite")
                z_j = math.exp(diff)
                if not math.isfinite(z_j):
                    raise ValueError("mha intermediate must be finite")
                z[j] = z_j
                row_sum += z_j
                if not math.isfinite(row_sum):
                    raise ValueError("mha intermediate must be finite")
            for j in allowed:
                p_j = z[j] / row_sum
                if not math.isfinite(p_j):
                    raise ValueError("mha intermediate must be finite")
                probs[sbase + j] = p_j
    # Output: y[head,i,r] = sum_j p[head,i,j] * V[head,j,r],
    # accumulated from 0.0 in ascending (i, head, r, j) order; masked
    # positions contribute 0.
    out_data = [0.0] * (q * h * d)
    for i in range(q):
        for head in range(h):
            for r in range(d):
                acc = 0.0
                for j in range(k):
                    if not snapshot_mask[i * k + j]:
                        continue
                    product = (
                        probs[(head * q + i) * k + j]
                        * snapshot_v[ki(head, j, r)]
                    )
                    if not math.isfinite(product):
                        raise ValueError("mha intermediate must be finite")
                    acc += product
                    if not math.isfinite(acc):
                        raise ValueError("mha intermediate must be finite")
                out_data[qi(head, i, r)] = acc
    if not (
        self.requires_grad or key.requires_grad or value.requires_grad
    ):
        return Tensor._make(
            out_data, False, (), None,
            grad_validator=lambda g: _validate_vector_grad(g, q * h * d),
        )
    parent_self, parent_key, parent_value = self, key, value
    saved_mask = snapshot_mask
    saved_p = list(probs)

    def backward_fn(grad):
        # H = G V^T, D[h,i,j] = p[h,i,j]*(H[h,i,j] -
        # sum_j p[h,i,j]*H[h,i,j]) over allowed positions,
        # dQ = D K / sqrt(d), dK = D^T Q / sqrt(d), dV = P^T G;
        # masked positions contribute 0.0. Every product and partial
        # sum is checked as it is produced, and the generic engine
        # validates each contribution and every merge into an existing
        # grad.
        h_mat = [0.0] * (h * q * k)
        d_mat = [0.0] * (h * q * k)
        dq = [0.0] * (q * h * d)
        dk = [0.0] * (k * h * d)
        dv = [0.0] * (k * h * d)
        for i in range(q):
            for head in range(h):
                for j in range(k):
                    acc = 0.0
                    for r in range(d):
                        product = (
                            grad[qi(head, i, r)]
                            * snapshot_v[ki(head, j, r)]
                        )
                        if not math.isfinite(product):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                        acc += product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                    h_mat[(head * q + i) * k + j] = acc
        for i in range(q):
            base = i * k
            allowed = [j for j in range(k) if saved_mask[base + j]]
            for head in range(h):
                sbase = (head * q + i) * k
                row_sum = 0.0
                for j in allowed:
                    product = saved_p[sbase + j] * h_mat[sbase + j]
                    if not math.isfinite(product):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                    row_sum += product
                    if not math.isfinite(row_sum):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                for j in allowed:
                    difference = h_mat[sbase + j] - row_sum
                    if not math.isfinite(difference):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                    d_ij = saved_p[sbase + j] * difference
                    if not math.isfinite(d_ij):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                    d_mat[sbase + j] = d_ij
        for i in range(q):
            for head in range(h):
                for r in range(d):
                    acc = 0.0
                    for j in range(k):
                        if not saved_mask[i * k + j]:
                            continue
                        product = (
                            d_mat[(head * q + i) * k + j]
                            * snapshot_k[ki(head, j, r)]
                        )
                        if not math.isfinite(product):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                        acc += product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                    contribution = acc / scale
                    if not math.isfinite(contribution):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                    dq[qi(head, i, r)] = contribution
        for j in range(k):
            for head in range(h):
                for r in range(d):
                    acc = 0.0
                    for i in range(q):
                        if not saved_mask[i * k + j]:
                            continue
                        product = (
                            d_mat[(head * q + i) * k + j]
                            * snapshot_q[qi(head, i, r)]
                        )
                        if not math.isfinite(product):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                        acc += product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                    contribution = acc / scale
                    if not math.isfinite(contribution):
                        raise ValueError(
                            "mha backward intermediate must be finite"
                        )
                    dk[ki(head, j, r)] = contribution
        for j in range(k):
            for head in range(h):
                for r in range(d):
                    acc = 0.0
                    for i in range(q):
                        if not saved_mask[i * k + j]:
                            continue
                        product = (
                            saved_p[(head * q + i) * k + j]
                            * grad[qi(head, i, r)]
                        )
                        if not math.isfinite(product):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                        acc += product
                        if not math.isfinite(acc):
                            raise ValueError(
                                "mha backward intermediate must be finite"
                            )
                    dv[ki(head, j, r)] = acc
        # One object may play several roles (e.g. key and value are
        # the same tensor); merge such roles into one contribution
        # per tensor, and submit only parents that require grad.
        merged = {}
        roles = (
            (parent_self, dq),
            (parent_key, dk),
            (parent_value, dv),
        )
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    )

def linear_batch(self, weight, bias, batch_size):
    if not isinstance(weight, Tensor):
        raise TypeError("weight must be a Tensor")
    if not isinstance(bias, Tensor):
        raise TypeError("bias must be a Tensor")
    # All three operands must hold non-empty 1D finite float lists;
    # data may have been mutated after construction, so re-validate at
    # call time. x is a B x n row-major batch, w the m x n row-major
    # matrix and b the length-m bias, so m = len(bias).
    x_data = _require_nonempty_float_vector(self, "linear_batch")
    w_data = _require_nonempty_float_vector(weight, "linear_batch")
    b_data = _require_nonempty_float_vector(bias, "linear_batch")
    if isinstance(batch_size, bool) or not isinstance(batch_size, int):
        raise TypeError("batch_size must be a positive int")
    if batch_size <= 0:
        raise ValueError("batch_size must be a positive int")
    if len(x_data) % batch_size != 0:
        raise ValueError("batch_size must divide the input length")
    B = batch_size
    n = len(x_data) // B
    m = len(b_data)
    # weight stores the m x n matrix in row-major order.
    if len(w_data) != m * n:
        raise ValueError("linear_batch weight length must equal m * n")
    # Snapshot all three operands so later caller-side mutation or
    # replacement of any input can change neither the forward result
    # nor a pending backward pass.
    snapshot_x = list(x_data)
    snapshot_w = list(w_data)
    snapshot_b = list(b_data)
    # out[q*m+o] = b[o] + sum_i x[q*n+i] * w[o*n+i], accumulated
    # starting from b[o] in ascending (q, o, i) order; a non-finite
    # product or partial sum aborts before a result tensor exists, so
    # no state changes.
    out_data = []
    for q in range(B):
        for o in range(m):
            acc = snapshot_b[o]
            for i in range(n):
                product = snapshot_x[q * n + i] * snapshot_w[o * n + i]
                if not math.isfinite(product):
                    raise ValueError(
                        "linear_batch intermediate must be finite"
                    )
                acc += product
                if not math.isfinite(acc):
                    raise ValueError(
                        "linear_batch intermediate must be finite"
                    )
            out_data.append(acc)
    if not (
        self.requires_grad
        or weight.requires_grad
        or bias.requires_grad
    ):
        return Tensor._make(out_data, False, (), None)
    parent_self, parent_weight, parent_bias = self, weight, bias

    def backward_fn(grad):
        # h = grad[q*m+o]; db[o] += h, dx[q*n+i] += h*w[o*n+i] and
        # dw[o*n+i] += h*x[q*n+i], accumulated from 0.0 in ascending
        # (q, o, i) order. A non-finite product or partial sum aborts
        # the whole pass before any grad is written.
        dx = [0.0] * (B * n)
        dw = [0.0] * (m * n)
        db = [0.0] * m
        for q in range(B):
            for o in range(m):
                h = grad[q * m + o]
                db[o] = db[o] + h
                if not math.isfinite(db[o]):
                    raise ValueError(
                        "linear_batch backward intermediate must be"
                        " finite"
                    )
                for i in range(n):
                    j = q * n + i
                    t = o * n + i
                    term_x = h * snapshot_w[t]
                    if not math.isfinite(term_x):
                        raise ValueError(
                            "linear_batch backward intermediate must be"
                            " finite"
                        )
                    dx[j] = dx[j] + term_x
                    if not math.isfinite(dx[j]):
                        raise ValueError(
                            "linear_batch backward intermediate must be"
                            " finite"
                        )
                    term_w = h * snapshot_x[j]
                    if not math.isfinite(term_w):
                        raise ValueError(
                            "linear_batch backward intermediate must be"
                            " finite"
                        )
                    dw[t] = dw[t] + term_w
                    if not math.isfinite(dw[t]):
                        raise ValueError(
                            "linear_batch backward intermediate must be"
                            " finite"
                        )
        # One object may play several roles (e.g. weight is also
        # bias); merge such roles into one contribution per tensor,
        # and submit only parents that require grad.
        merged = {}
        roles = (
            (parent_self, dx),
            (parent_weight, dw),
            (parent_bias, db),
        )
        for parent, value in roles:
            if not parent.requires_grad:
                continue
            entry = merged.get(id(parent))
            if entry is None:
                merged[id(parent)] = [parent, value]
            else:
                combined = _merge_grad(entry[1], value)
                _ensure_finite_grad(combined)
                entry[1] = combined
        return [(entry[0], entry[1]) for entry in merged.values()]

    return Tensor._make(
        out_data,
        True,
        (parent_self, parent_weight, parent_bias),
        backward_fn,

    raise TypeError(
        "data must be a finite float scalar or a non-empty 1D float list"
    )


def _ensure_finite_data(data):
    """ValueError if a forward result contains a non-finite value."""
    values = data if isinstance(data, list) else [data]
    if not all(math.isfinite(v) for v in values):
        raise ValueError("forward result must be finite")


def _ensure_finite_grad(value):
    """ValueError if a gradient to accumulate contains a non-finite value."""
    values = value if isinstance(value, list) else [value]
    if not all(math.isfinite(v) for v in values):
        raise ValueError("gradient must be finite")


def _finite_power(base, exponent, message="power result must be finite"):
    """Raise base to exponent, mapping overflow/non-finite to ValueError."""
    try:
        result = base ** exponent
    except OverflowError:
        raise ValueError(message)
    if not math.isfinite(result):
        raise ValueError(message)
    return result


def _finite_exp(x, message="exp result must be finite"):
    """Evaluate math.exp, mapping overflow/non-finite to ValueError."""
    try:
        result = math.exp(x)
    except OverflowError:
        raise ValueError(message)
    if not math.isfinite(result):
        raise ValueError(message)
    return result


def _broadcast_apply(a, b, op):
    """Apply op over scalar/vector operands with scalar broadcasting."""
    a_vector = isinstance(a, list)
    b_vector = isinstance(b, list)
    if not a_vector and not b_vector:
        return op(a, b)
    if a_vector and not b_vector:
        return [op(x, b) for x in a]
    if not a_vector and b_vector:
        return [op(a, y) for y in b]
    if len(a) != len(b):
        raise ValueError("vector lengths must match")
    return [op(x, y) for x, y in zip(a, b)]


def _map_unary(data, op):
    """Apply op elementwise over a scalar or vector."""
    if isinstance(data, list):
        return [op(x) for x in data]
    return op(data)


def _reduce_like(parent_data, value):
    """Sum a broadcast gradient back down to the parent's shape."""
    if not isinstance(parent_data, list) and isinstance(value, list):
        return sum(value)
    return value


def _merge_grad(a, b):
    """Combine two gradient contributions of identical shape."""
    if isinstance(a, list):
        return [x + y for x, y in zip(a, b)]
    return a + b


def _sub_grad(a, b):
    """Subtract two gradient values of identical shape."""
    if isinstance(a, list):
        return [x - y for x, y in zip(a, b)]
    return a - b


def _same_grad_shape(a, b):
    """True when two gradient values have matching scalar/vector shape."""
    if isinstance(a, list) or isinstance(b, list):
        return (
            isinstance(a, list)
            and isinstance(b, list)
            and len(a) == len(b)
        )
    return True


def _validate_grad(grad, like):
    """Validate an externally supplied outgoing gradient against tensor data."""
    if isinstance(grad, bool):
        raise TypeError("grad must be a float or a list of floats")
    if isinstance(like, float):
        if isinstance(grad, list):
            raise ValueError("grad shape must match tensor shape")
        if not isinstance(grad, float):
            raise TypeError("grad must be a float for a scalar tensor")
        if not math.isfinite(grad):
            raise ValueError("grad must be finite")
        return grad
    if isinstance(grad, list):
        if len(grad) != len(like):
            raise ValueError("grad shape must match tensor shape")
        return [_as_finite_float(x) for x in grad]
    if isinstance(grad, float):
        raise ValueError("grad shape must match tensor shape")
    raise TypeError("grad must be a float or a list of floats")


def _validate_vector_grad(grad, length):
    """Validate an outgoing grad that must be a finite-float list.

    bool/int/float scalars (including a bool, which is also an int), an
    omitted grad, wrong-length or non-finite lists are ValueError; None
    and any other non-list type are TypeError; a list containing a
    non-float (bool/int included) is TypeError. Matches the bmm/cumprod
    rule for vector outputs.
    """
    if grad is _MISSING or isinstance(grad, (bool, int, float)):
        raise ValueError("grad must be a list of finite floats")
    if grad is None or not isinstance(grad, list):
        raise TypeError("grad must be a list of finite floats")
    if len(grad) != length:
        raise ValueError("grad length must match tensor length")
    return [_as_finite_float(x) for x in grad]


def _require_nonempty_float_vector(tensor, op):
    """Validate the shared log_softmax/cross_entropy preconditions."""
    data = tensor.data
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError(op + " requires a non-empty 1D float list")
    for value in data:
        if isinstance(value, bool) or not isinstance(value, float):
            raise TypeError(op + " data elements must be floats")
    if not isinstance(tensor.requires_grad, bool):
        raise TypeError("requires_grad must be a bool")
    for value in data:
        if not math.isfinite(value):
            raise ValueError(op + " data elements must be finite")
    return data


def _stable_sigmoid_value(x):
    """Evaluate sigmoid(x) stably, never exponentiating a large positive.

    For x >= 0: e = exp(-x), d = 1 + e, y = 1/d.
    For x < 0:  e = exp(x),  d = 1 + e, y = e/d.
    ValueError if any of e, d, y is non-finite.
    """
    if x >= 0.0:
        e = math.exp(-x)
        if not math.isfinite(e):
            raise ValueError("sigmoid intermediate must be finite")
        d = 1.0 + e
        if not math.isfinite(d):
            raise ValueError("sigmoid intermediate must be finite")
        y = 1.0 / d
        if not math.isfinite(y):
            raise ValueError("sigmoid intermediate must be finite")
        return y
    e = math.exp(x)
    if not math.isfinite(e):
        raise ValueError("sigmoid intermediate must be finite")
    d = 1.0 + e
    if not math.isfinite(d):
        raise ValueError("sigmoid intermediate must be finite")
    y = e / d
    if not math.isfinite(y):
        raise ValueError("sigmoid intermediate must be finite")
    return y


def _log_softmax_values(data):
    """Compute log-softmax values stably.

    Shift by the maximum so exp is only ever evaluated on values in
    (-inf, 0]; exp(x_i) directly is never computed.
    """
    m = max(data)
    diffs = []
    z = []
    for value in data:
        diff = value - m
        if not math.isfinite(diff):
            raise ValueError("log_softmax intermediate must be finite")
        diffs.append(diff)
        z_i = math.exp(diff)
        if not math.isfinite(z_i):
            raise ValueError("log_softmax intermediate must be finite")
        z.append(z_i)
    s = sum(z)
    if not math.isfinite(s):
        raise ValueError("log_softmax intermediate must be finite")
    log_s = math.log(s)
    if not math.isfinite(log_s):
        raise ValueError("log_softmax intermediate must be finite")
    out = []
    for diff in diffs:
        l_i = diff - log_s
        if not math.isfinite(l_i):
            raise ValueError("log_softmax intermediate must be finite")
        out.append(l_i)
    return out


class Tensor:
    def __init__(self, data, requires_grad=False):
        normalized = _validate_data(data)
        if not isinstance(requires_grad, bool):
            raise TypeError("requires_grad must be a bool")
        self.data = normalized
        self.requires_grad = requires_grad
        self.grad = None
        self._parents = ()
        self._backward_fn = None
        self._backward_record = None
        # Per-tensor override for externally supplied backward() grads;
        # None means use the generic _validate_grad rules.
        self._grad_validator = None

